CREATE TABLE public."Restaurants" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" varchar(150) NOT NULL,
    "Cuisine" varchar(150) NOT NULL,
    "Rating" numeric(3,2) NOT NULL,
    "DeliveryTime" varchar(50) NOT NULL,
    "Price" varchar(20) NOT NULL,
    "ImageKey" varchar(20) NOT NULL,
    "IsActive" boolean NOT NULL
);

CREATE TABLE public."Users" (
    "Id" uuid PRIMARY KEY,
    "UserName" varchar(50) NOT NULL,
    "NormalizedUserName" varchar(50) NOT NULL,
    "Email" varchar(254) NOT NULL,
    "NormalizedEmail" varchar(254) NOT NULL,
    "FirstName" varchar(100) NOT NULL,
    "LastName" varchar(100) NOT NULL,
    "PasswordHash" varchar(512) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "VendorRestaurantId" integer NULL,
    CONSTRAINT "FK_Users_Restaurants_VendorRestaurantId"
        FOREIGN KEY ("VendorRestaurantId")
        REFERENCES public."Restaurants" ("Id")
        ON DELETE RESTRICT
);

CREATE UNIQUE INDEX "IX_Users_NormalizedEmail"
    ON public."Users" ("NormalizedEmail");
CREATE UNIQUE INDEX "IX_Users_NormalizedUserName"
    ON public."Users" ("NormalizedUserName");
CREATE UNIQUE INDEX "IX_Users_VendorRestaurantId"
    ON public."Users" ("VendorRestaurantId")
    WHERE "VendorRestaurantId" IS NOT NULL;

CREATE TABLE public."MenuItems" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "RestaurantId" integer NOT NULL,
    "Name" varchar(100) NOT NULL,
    "Description" varchar(500) NOT NULL,
    "Price" numeric(10,2) NOT NULL,
    "ImageUrl" varchar(500) NULL,
    "IsAvailable" boolean NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "FK_MenuItems_Restaurants_RestaurantId"
        FOREIGN KEY ("RestaurantId")
        REFERENCES public."Restaurants" ("Id")
        ON DELETE CASCADE
);
CREATE INDEX "IX_MenuItems_RestaurantId_IsAvailable"
    ON public."MenuItems" ("RestaurantId", "IsAvailable");

CREATE TABLE public."Orders" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "RestaurantId" integer NOT NULL,
    "CustomerId" uuid NOT NULL,
    "CustomerName" varchar(201) NOT NULL,
    "CustomerEmail" varchar(254) NOT NULL,
    "CustomerPhone" varchar(30) NOT NULL,
    "DeliveryAddress" varchar(300) NOT NULL,
    "Subtotal" numeric(10,2) NOT NULL,
    "DeliveryFee" numeric(10,2) NOT NULL,
    "ServiceFee" numeric(10,2) NOT NULL,
    "Total" numeric(10,2) NOT NULL,
    "Status" varchar(20) NOT NULL,
    "PlacedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "FK_Orders_Restaurants_RestaurantId"
        FOREIGN KEY ("RestaurantId")
        REFERENCES public."Restaurants" ("Id")
        ON DELETE RESTRICT,
    CONSTRAINT "FK_Orders_Users_CustomerId"
        FOREIGN KEY ("CustomerId")
        REFERENCES public."Users" ("Id")
        ON DELETE RESTRICT
);
CREATE INDEX "IX_Orders_CustomerId" ON public."Orders" ("CustomerId");
CREATE INDEX "IX_Orders_RestaurantId_PlacedAt"
    ON public."Orders" ("RestaurantId", "PlacedAt");

CREATE TABLE public."OrderItems" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "OrderId" integer NOT NULL,
    "Name" varchar(100) NOT NULL,
    "UnitPrice" numeric(10,2) NOT NULL,
    "Quantity" integer NOT NULL,
    CONSTRAINT "FK_OrderItems_Orders_OrderId"
        FOREIGN KEY ("OrderId")
        REFERENCES public."Orders" ("Id")
        ON DELETE CASCADE
);
CREATE INDEX "IX_OrderItems_OrderId" ON public."OrderItems" ("OrderId");

ALTER TABLE public."Restaurants" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."Users" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."MenuItems" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."Orders" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."OrderItems" ENABLE ROW LEVEL SECURITY;

REVOKE ALL PRIVILEGES ON TABLE
    public."Restaurants",
    public."Users",
    public."MenuItems",
    public."Orders",
    public."OrderItems"
FROM anon, authenticated;

INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES (
    'menu-images',
    'menu-images',
    true,
    5242880,
    ARRAY['image/jpeg', 'image/png', 'image/webp']
)
ON CONFLICT (id) DO UPDATE
SET public = EXCLUDED.public,
    file_size_limit = EXCLUDED.file_size_limit,
    allowed_mime_types = EXCLUDED.allowed_mime_types;

